class Solution {
public:
    int poorPigs(int buckets, int minutesToDie, int minutesToTest) {
        int T = minutesToTest / minutesToDie;
        long long states = 1;
        int pigs = 0;
        while (states < buckets) {
            states *= (T + 1);
            pigs++;
        }
        return pigs;
    }
};
